// ============================================================================
// ParityTests.swift — Phase 5 verification gates. Every fixture here is
// generated by scripts/tools/gen-parity-fixtures.mjs from the WEB golden
// engines and shipped into Fixtures/ by scripts/tools/sync-native-assets.mjs.
// These tests are THE "native diff = 0 ms" + ".sadaqa cross-OS" proof.
// ============================================================================

import XCTest
import GRDB
@testable import SadaqaJaria

final class FixtureLoader {
    /// Fixtures live in `apps/ios-native/Fixtures` and are copied into the test
    /// bundle (either as a `Fixtures` folder reference or flat by XcodeGen).
    static func read(_ rel: String) throws -> JSONValue {
        let bundle = Bundle(for: FixtureLoader.self)
        let leaf = (rel as NSString).lastPathComponent
        let candidates: [URL?] = [
            bundle.url(forResource: "Fixtures", withExtension: nil)?.appendingPathComponent(rel),
            bundle.resourceURL?.appendingPathComponent(rel),
            bundle.resourceURL?.appendingPathComponent(leaf),
            URL(fileURLWithPath: #filePath)
                .deletingLastPathComponent()
                .deletingLastPathComponent()
                .appendingPathComponent("Fixtures")
                .appendingPathComponent(rel),
        ]
        guard let url = candidates.compactMap({ $0 }).first(where: { FileManager.default.fileExists(atPath: $0.path) }) else {
            XCTFail("missing fixture: \(rel)")
            throw NSError(domain: "fixtures", code: 1)
        }
        return try JSONValue.parse(String(contentsOf: url, encoding: .utf8))
    }
}

// ---------------------------------------------------------------------------
// Prayer parity — 6 cities × DST months × 2 variants, every day, 0 ms.
// ---------------------------------------------------------------------------

final class PrayerParityTests: XCTestCase {

    func testPrayerTimesZeroMsDriftAcrossMonthGrids() throws {
        let manifest = try FixtureLoader.read("manifest.json")
        let files = try XCTUnwrap(manifest["files"]?.arrayValue)
        let prayerFiles = try files.compactMap { f -> String? in
            guard let p = f["path"]?.stringValue, p.contains("/prayer/") else { return nil }
            return String(p.split(separator: "/").last!)
        }

        XCTAssertGreaterThanOrEqual(prayerFiles.count, 24, "expected ≥24 prayer fixture grids")
        var checked = 0
        for file in prayerFiles {
            let fx = try FixtureLoader.read("prayer/\(file)")
            let meta = try XCTUnwrap(fx["meta"])
            let opts = EngineOptions(
                lat: meta["lat"]!.doubleValue!,
                lng: meta["lng"]!.doubleValue!,
                timeZone: meta["timeZone"]!.stringValue!,
                method: meta["method"]!.stringValue!,
                madhab: meta["madhab"]!.stringValue!,
                highLatitudeRule: meta["highLatitudeRule"]!.stringValue!)
            for day in fx["days"]!.arrayValue! {
                let parts = day["date"]!.stringValue!.split(separator: "-").map { Int($0)! }
                let got = try PrayerEngine.computeForDate(y: parts[0], mo: parts[1] - 1, d: parts[2], opts: opts)
                for name in PrayerName.allCases {
                    let want = day["prayers"]![name.rawValue]!.int64Value!
                    XCTAssertEqual(got[name], want, "\(file) \(day["date"]!.stringValue!) \(name.rawValue)")
                    checked += 1
                }
                let prevIsha = day["previousIsha"]!.int64Value!
                let sched = try PrayerEngine.daySchedule(day["date"]!.stringValue!, opts)
                XCTAssertEqual(sched.previousIsha, prevIsha, "\(file) \(day["date"]!.stringValue!) previousIsha")
                let sun = day["sunnah"]!
                let windows = try PrayerEngine.sunnahWindows(day["date"]!.stringValue!, opts)
                XCTAssertEqual(windows.duha, sun["duha"]!.int64Value!, "\(file) duha")
                XCTAssertEqual(windows.duhaEnd, sun["duhaEnd"]!.int64Value!, "\(file) duhaEnd")
                XCTAssertEqual(windows.midnight, sun["midnight"]!.int64Value!, "\(file) midnight")
                XCTAssertEqual(windows.lastThird, sun["lastThird"]!.int64Value!, "\(file) lastThird")
            }
            for probe in fx["nextProbes"]!.arrayValue! {
                let got = try PrayerEngine.next(probe["now"]!.int64Value!, opts)
                let want = probe["expected"]!
                XCTAssertEqual(got.name.rawValue, want["name"]!.stringValue!, "\(file) nextProbes name")
                XCTAssertEqual(got.at, want["at"]!.int64Value!, "\(file) nextProbes at")
                XCTAssertEqual(got.previousName?.rawValue ?? "", want["previous"]!["name"]!.stringValue!, "\(file) nextProbes previous")
                XCTAssertEqual(got.previousAt ?? 0, want["previous"]!["at"]!.int64Value!, "\(file) nextProbes previousAt")
            }
        }
        XCTAssertGreaterThan(checked, 4000, "prayer parity checked instants")
    }
}

// ---------------------------------------------------------------------------
// Smart card parity — §9 resolver matrix (6 kinds × 6 cities).
// ---------------------------------------------------------------------------

final class SmartCardParityTests: XCTestCase {

    func testSmartCardKindsMatchWebResolver() throws {
        let fx = try FixtureLoader.read("smart-card/cases.json")
        let cases = try XCTUnwrap(fx["cases"]?.arrayValue)
        XCTAssertEqual(cases.count, 42, "§9 matrix size")
        var kinds = Set<String>()
        for c in cases {
            let name = c["name"]!.stringValue!
            let cityKey = String(name.split(separator: ":").first!)
            let opts = Self.opts(for: cityKey)
            let engine = PrayerEngine.bind(opts)
            let card = SmartCardResolver.resolve(now: c["now"]!.int64Value!, engine: engine)
            let want = c["expectedKind"]!.stringValue!
            kinds.insert(card.kind.rawValue)
            XCTAssertEqual(card.kind.rawValue, want, name)
        }
        for expected in ["kahf", "after_prayer", "qiyam", "morning", "evening", "next_prayer"] {
            XCTAssertTrue(kinds.contains(expected), "kind missing from matrix: \(expected)")
        }
    }

    static func opts(for cityKey: String) -> EngineOptions {
        switch cityKey {
        case "makkah": return EngineOptions(lat: 21.4225, lng: 39.8262, timeZone: "Asia/Riyadh")
        case "london": return EngineOptions(lat: 51.5074, lng: -0.1278, timeZone: "Europe/London")
        case "anchorage": return EngineOptions(lat: 61.2181, lng: -149.9003, timeZone: "America/Anchorage")
        case "auckland": return EngineOptions(lat: -36.8485, lng: 174.7633, timeZone: "Pacific/Auckland")
        case "losangeles": return EngineOptions(lat: 34.0522, lng: -118.2437, timeZone: "America/Los_Angeles")
        case "tokyo": return EngineOptions(lat: 35.6762, lng: 139.6503, timeZone: "Asia/Tokyo")
        default: fatalError("unknown fixture city \(cityKey)")
        }
    }
}

// ---------------------------------------------------------------------------
// Backup codec parity — validator refusals, merge table, real .sadaqa file.
// ---------------------------------------------------------------------------

final class BackupCodecParityTests: XCTestCase {

    func testValidatorVerdicts() throws {
        let fx = try FixtureLoader.read("backup/validate-cases.json")
        let cases = try XCTUnwrap(fx["cases"]?.arrayValue)
        XCTAssertGreaterThanOrEqual(cases.count, 29)
        for c in cases {
            let verdict = BackupCodec.validateBackup(manifest: c["manifest"], payload: c["payload"])
            XCTAssertEqual(verdict.ok, c["expectOk"]!.boolValue!, "case \(c["name"]!.stringValue!) ok")
            XCTAssertEqual(verdict.errors.count, c["expectErrorCount"]!.intValue!, "case \(c["name"]!.stringValue!) error count (got \(verdict.errors.prefix(2)))")
        }
    }

    func testMergeTable() throws {
        let fx = try FixtureLoader.read("backup/merge-cases.json")
        let cases = try XCTUnwrap(fx["cases"]?.arrayValue)
        XCTAssertGreaterThanOrEqual(cases.count, 15)
        for c in cases {
            var local: [String: [String: JSONValue]] = [:]
            for (group, groupValue) in c["local"]!.objectValue ?? [:] {
                var m: [String: JSONValue] = [:]
                for e in groupValue.arrayValue ?? [] { m[e["uuid"]!.stringValue!] = e }
                local[group] = m
            }
            let result = try BackupCodec.mergePayload(
                local: local, payload: c["payload"], mode: c["mode"]!.stringValue!,
                now: Int64(c["now"]!.doubleValue!))
            let want = c["expected"]!
            // report
            XCTAssertEqual(result.report.added, want["report"]!["added"]!.intValue!, c["name"]!.stringValue!)
            XCTAssertEqual(result.report.updated, want["report"]!["updated"]!.intValue!, c["name"]!.stringValue!)
            XCTAssertEqual(result.report.conflicts, want["report"]!["conflicts"]!.intValue!, c["name"]!.stringValue!)
            XCTAssertEqual(result.report.skipped, want["report"]!["skipped"]!.intValue!, c["name"]!.stringValue!)
            XCTAssertEqual(result.report.deleted, want["report"]!["deleted"]!.intValue!, c["name"]!.stringValue!)
            // mutations: uuid + action + entity canonical bytes
            let wantMutations = want["mutations"]!.arrayValue!
            XCTAssertEqual(result.mutations.count, wantMutations.count, c["name"]!.stringValue!)
            for (got, w) in zip(result.mutations, wantMutations) {
                XCTAssertEqual(got.group, w["group"]!.stringValue, c["name"]!.stringValue!)
                XCTAssertEqual(got.uuid, w["uuid"]!.stringValue, c["name"]!.stringValue!)
                XCTAssertEqual(got.action, w["action"]!.stringValue, c["name"]!.stringValue!)
                XCTAssertEqual(CanonicalJSON.serialize(got.entity), CanonicalJSON.serialize(w["entity"]!), c["name"]!.stringValue!)
            }
        }
    }

    /// The cross-OS contract: a REAL web-exported `.sadaqa` file parses,
    /// validates, and its sha-256 integrity digest matches byte-for-byte.
    func testWebExportedFileImportableOnIOS() throws {
        let fx = try FixtureLoader.read("backup/sample-export.json")
        let manifest = fx["manifest"]
        let payloadJson = fx["payloadJson"]!.stringValue!
        // integrity: sha-256 of the EXACT payload bytes
        XCTAssertEqual(sha256Hex(payloadJson), manifest!["integrity"]!.stringValue!, "integrity digest over payload bytes")
        let verdict = BackupCodec.validateBackup(manifest: manifest, payload: try JSONValue.parse(payloadJson))
        XCTAssertTrue(verdict.ok, "validator refuses web export: \(verdict.errors.prefix(3))")
        let counts = verdict.counts
        XCTAssertEqual(counts["reading"], 7, "reading entity count; 2026-11: +2 khatmahPageLog")
        XCTAssertEqual(counts["dhikr"], 7, "dhikr entity count")
        XCTAssertEqual(counts["prefs"], 2, "prefs entity count")
        XCTAssertEqual(counts["meta"], 2, "meta entity count")
    }

    func testTamperedPayloadFailsIntegrityCheck() throws {
        // integrity recompute (2026-11 finding): the digest is recomputed over
        // canonical payload bytes on import; a structurally-valid payload whose
        // bytes changed after export must NOT hash to manifest.integrity.
        let fx = try FixtureLoader.read("backup/sample-export.json")
        let manifest = fx["manifest"]
        let payload = try JSONValue.parse(fx["payloadJson"]!.stringValue!)
        XCTAssertEqual(
            BackupCodec.integrityOf(payloadJson: CanonicalJSON.serialize(payload)),
            manifest!["integrity"]!.stringValue!,
            "golden bytes verify")
        let tampered = try JSONValue.parse(
            fx["payloadJson"]!.stringValue!.replacingOccurrences(of: "\"page\":303", with: "\"page\":304"))
        XCTAssertNotEqual(
            BackupCodec.integrityOf(payloadJson: CanonicalJSON.serialize(tampered)),
            manifest!["integrity"]!.stringValue!,
            "one flipped field must change the digest")
        XCTAssertTrue(
            BackupCodec.validateBackup(manifest: manifest, payload: tampered).ok,
            "the validator alone accepts the tampered shape — the digest check is the guard")
    }
}

// ---------------------------------------------------------------------------
// UUIDv7 byte-parity — synthetic ids identical across all four targets.
// ---------------------------------------------------------------------------

final class UUID7ParityTests: XCTestCase {

    func testSynthUuid7ByteIdenticalWithWeb() throws {
        let fx = try FixtureLoader.read("uuid7/synth.json")
        let pinned = Int64(fx["meta"]!["pinnedNow"]!.doubleValue!)
        for v in fx["synth"]!.arrayValue! {
            let got = UUIDv7.synthUuid7(v["key"]!.stringValue!, now: pinned)
            XCTAssertEqual(got, v["uuid"]!.stringValue!, "synth uuid for \(v["key"]!.stringValue!)")
        }
    }

    func testUuid7ShapeAndOrdering() {
        let base: Int64 = 1_764_300_000_000
        let a = UUIDv7.uuid7(now: base)
        let b = UUIDv7.uuid7(now: base + 1)
        XCTAssertTrue(UUIDv7.isUUIDv7Shape(a))
        XCTAssertTrue(UUIDv7.isUUIDv7Shape(b))
        // 48-bit ms timestamp is the high segment → monotonic ordering
        XCTAssertLessThan(String(a.prefix(13)), String(b.prefix(13)))
    }

    func testPayloadGroupOrderMatchesWebBytes() {
        // top-level groups serialize in the golden's fixed order (reading, dhikr, prefs, meta)
        let payload = BackupCodec.toPayloadGroups([
            "meta": [:], "prefs": [:], "dhikr": [:], "reading": [:],
        ])
        XCTAssertTrue(CanonicalJSON.serialize(payload).hasPrefix("{\"reading\":"), "group order reading,dhikr,prefs,meta")
    }
}

// ---------------------------------------------------------------------------
// Hijri + Qibla parity.
// ---------------------------------------------------------------------------

final class HijriQiblaParityTests: XCTestCase {

    func testHijriRoundTripVectors() throws {
        let fx = try FixtureLoader.read("hijri/roundtrip.json")
        for w in fx["weekly"]!.arrayValue! {
            let iso = w["gregorian"]!.stringValue!
            let got = HijriEngine.toHijri(iso)
            let want = w["hijri"]!
            XCTAssertEqual(got.y, want["y"]!.intValue!, iso)
            XCTAssertEqual(got.m, want["m"]!.intValue!, iso)
            XCTAssertEqual(got.d, want["d"]!.intValue!, iso)
        }
        for p in fx["probes"]!.arrayValue! {
            let got = try HijriEngine.fromHijri(HijriDate(y: p["hijri"]!["y"]!.intValue!, m: p["hijri"]!["m"]!.intValue!, d: p["hijri"]!["d"]!.intValue!))
            // expectGregorian records the pinned anchor where present; umalqura
            // truth is the generator's `gotGregorian` in all cases
            XCTAssertEqual(got, p["gotGregorian"]!.stringValue!, "fromHijri \(p["hijri"]!)")
        }
        for t in fx["mustThrow"]!.arrayValue! {
            XCTAssertThrowsError(try HijriEngine.fromHijri(HijriDate(y: t["hijri"]!["y"]!.intValue!, m: t["hijri"]!["m"]!.intValue!, d: t["hijri"]!["d"]!.intValue!)), "\(t["hijri"]!) must throw")
        }
        for a in fx["adjusts"]!.arrayValue! {
            if case .object(let o) = a {
                let adjust = o["adjust"]!.intValue!
                let got = HijriEngine.withAdjust("2026-11-17", adjust)
                XCTAssertEqual(got, HijriDate(
                    y: o["2026-11-17"]!["y"]!.intValue!,
                    m: o["2026-11-17"]!["m"]!.intValue!,
                    d: o["2026-11-17"]!["d"]!.intValue!), "adjust \(adjust)")
            }
        }
    }

    func testIslamicEvents2026() throws {
        let fx = try FixtureLoader.read("hijri/events.json")
        let got = HijriEngine.events(2026)
        let want = fx["events2026"]!.arrayValue!
        XCTAssertEqual(got.count, want.count)
        for (g, w) in zip(got, want) {
            XCTAssertEqual(g.key, w["key"]!.stringValue)
            XCTAssertEqual(g.gregorian, w["gregorian"]!.stringValue)
        }
    }

    func testQiblaBearings() throws {
        let fx = try FixtureLoader.read("qibla/bearings.json")
        for p in fx["points"]!.arrayValue! {
            let lat = p["lat"]!.doubleValue!, lng = p["lng"]!.doubleValue!
            XCTAssertEqual(QiblaEngine.qiblaBearing(lat: lat, lng: lng), p["bearing"]!.doubleValue!, accuracy: 1e-9, p["name"]!.stringValue!)
            XCTAssertEqual(QiblaEngine.distanceKm(lat: lat, lng: lng), p["distanceKm"]!.doubleValue!, accuracy: 1e-9, p["name"]!.stringValue!)
        }
    }
}

// ---------------------------------------------------------------------------
// Schema contract — the shipped db matches tableinfo.json exactly
// (GRDB opens the SAME sadaqa.db the web ships, so this proves the bundled
// file + sync script, not a native re-creation).
// ---------------------------------------------------------------------------

final class SchemaContractTests: XCTestCase {

    func testBundledDatabaseMatchesSchemaContract() throws {
        let contract = try FixtureLoader.read("schema/tableinfo.json")
        let tables = try XCTUnwrap(contract["tables"]?.objectValue)
        let bundle = Bundle(for: FixtureLoader.self)
        let repoDb = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("Resources/sadaqa.db")
        let bundledDb = bundle.url(forResource: "sadaqa", withExtension: "db")
        // Prefer the app bundle resource when running via the host app target
        let dbUrl = Bundle.main.url(forResource: "sadaqa", withExtension: "db") ?? bundledDb ?? repoDb
        let db = try DatabaseQueue(path: dbUrl.path)
        try db.read { db in
            for (name, spec) in tables {
                let columns = try Row.fetchAll(db, sql: "PRAGMA table_info(\(name))")
                let want = spec["columns"]!.arrayValue!
                XCTAssertEqual(columns.count, want.count, "table \(name) column count")
                for (c, w) in zip(columns, want) {
                    XCTAssertEqual(c["name"] as String?, w["name"]!.stringValue, "table \(name)")
                    XCTAssertEqual((c["type"] as String? ?? "").uppercased(), (w["type"]!.stringValue ?? "").uppercased(), "table \(name) col \(w["name"]!.stringValue!) type")
                    XCTAssertEqual(c["notnull"] as Int? ?? 0, w["notnull"]!.boolValue! ? 1 : 0, "table \(name) col \(w["name"]!.stringValue!) notnull")
                    XCTAssertEqual((c["pk"] as Int? ?? 0) > 0, w["pk"]!.intValue! > 0, "table \(name) col \(w["name"]!.stringValue!) pk")
                    let wantDflt = w["dflt"]?.stringValue
                    let gotDflt = c["dflt_value"] as String?
                    if wantDflt != nil || gotDflt != nil {
                        XCTAssertEqual(wantDflt, gotDflt, "table \(name) col \(w["name"]!.stringValue!) default")
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Cross-platform round-trip: web export fixture imported into GRDB
// (Merge and Replace) — the Phase 5 checklist item executed on iOS.
// ---------------------------------------------------------------------------

final class ExportImportRoundTripTests: XCTestCase {

    /// A fresh Application-Support-shaped temp db per test (never the real one).
    func makeDb() throws -> SadaqaDatabase {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("p5-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let repoDb = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("Resources/sadaqa.db")
        let testDb = Bundle(for: FixtureLoader.self).url(forResource: "sadaqa", withExtension: "db")
        let src = Bundle.main.url(forResource: "sadaqa", withExtension: "db") ?? testDb ?? repoDb
        let dst = dir.appendingPathComponent("sadaqa.db")
        try FileManager.default.copyItem(at: src, to: dst)
        let q = try DatabaseQueue(path: dst.path)
        return SadaqaDatabase(queue: q)
    }

    func testImportWebExportMergeThenReplace() throws {
        let fx = try FixtureLoader.read("backup/sample-export.json")
        let text = CanonicalJSON.serialize(.object([
            "manifest": fx["manifest"]!, "payload": try JSONValue.parse(fx["payloadJson"]!.stringValue!),
        ]))
        let db = try makeDb()
        _ = try db.deviceId()

        // 1. Merge into the empty seed → all inserts
        let merge = try db.importBackup(text: text, mode: "merge")
        XCTAssertEqual(merge.added, 18, "merge adds every fixture entity (7+7+2+2; 2026-11: +2 khatmahPageLog)")
        try db.queue.read { db in
            XCTAssertEqual(try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM bookmarks"), 2)
            XCTAssertEqual(try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM tasbih_sessions"), 3)
            XCTAssertEqual(try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM khatmah_page_log"), 2)
            let theme = try Row.fetchOne(db, sql: "SELECT value FROM user_settings WHERE key = 'theme'")
            XCTAssertEqual(theme?["value"] as String?, "\"dark\"")
        }

        // 2. Local edit (bookmark page 2 → newer) then re-merge: conflict (local alive & newer)
        let newer = Int64(1_800_000_000_000)
        try db.queue.write { db in
            try db.execute(sql: "UPDATE bookmarks SET page = 9, updated_at = ? WHERE page = 2", arguments: [newer])
        }
        let merge2 = try db.importBackup(text: text, mode: "merge")
        XCTAssertEqual(merge2.conflicts, 1, "local newer alive bookmark wins → conflict")

        // 3. Full Replace wipes and restores exactly the payload
        let replace = try db.importBackup(text: text, mode: "replace")
        XCTAssertEqual(replace.added, 18, "replace inserts all payload entities")
        try db.queue.read { db in
            XCTAssertEqual(try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM bookmarks"), 2)
            let page = try Int.fetchOne(db, sql: "SELECT page FROM bookmarks WHERE label_ar = 'الفاتحة'")
            XCTAssertEqual(page, 2, "replace restored the payload copy verbatim")
            XCTAssertEqual(try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM user_settings WHERE key = 'device_id'"), 1, "device_id survives replace")
            let audit = try Row.fetchAll(db, sql: "SELECT * FROM backup_log ORDER BY id DESC LIMIT 1")
            XCTAssertEqual(audit.first?["direction"] as String?, "import")
        }

        // 4. iOS export → same validator → integrity holds (round-trip closure)
        let (manifest, payloadJson) = try db.buildExportPayload(now: 1_764_300_000_000)
        XCTAssertEqual(manifest["integrity"]!.stringValue, sha256Hex(payloadJson), "iOS export integrity")
        let verdict = BackupCodec.validateBackup(manifest: manifest, payload: try JSONValue.parse(payloadJson))
        XCTAssertTrue(verdict.ok, "iOS export validates: \(verdict.errors.prefix(3))")
    }
}

// ---------------------------------------------------------------------------
// Write-path regression tests — atomic transactions without GRDB reentrancy,
// zero-byte DB recovery, and bookmark/tasbih/adhkar persistence.
// ---------------------------------------------------------------------------

final class DatabaseWritePathTests: XCTestCase {

    func makeDb() throws -> SadaqaDatabase {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("wp-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let repoDb = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .appendingPathComponent("Resources/sadaqa.db")
        let testDb = Bundle(for: FixtureLoader.self).url(forResource: "sadaqa", withExtension: "db")
        let src = Bundle.main.url(forResource: "sadaqa", withExtension: "db") ?? testDb ?? repoDb
        let dst = dir.appendingPathComponent("sadaqa.db")
        try FileManager.default.copyItem(at: src, to: dst)
        let q = try DatabaseQueue(path: dst.path)
        return SadaqaDatabase(queue: q)
    }

    func testIncrementDhikrTapRecordsStateAndStreakWithoutReentrancy() throws {
        let db = try makeDb()
        let day = "2026-11-18"
        let now: Int64 = 1_794_988_800_000
        let rows = try db.queue.read { q in
            try Row.fetchAll(q, sql: "SELECT item_id, category_id, count_target FROM athkar_items WHERE count_target > 0 LIMIT 1")
        }
        let item = try XCTUnwrap(rows.first)
        let itemId: String = item["item_id"]
        let catId: String = item["category_id"]
        let target: Int = item["count_target"]

        var count = 0
        for step in 0..<target {
            count = try db.incrementDhikrTap(
                itemId: itemId,
                categoryId: catId,
                currentCount: step,
                target: target,
                dayKey: day,
                now: now + Int64(step * 100)
            )
            XCTAssertEqual(count, step + 1)
        }
        let capped = try db.incrementDhikrTap(itemId: itemId, categoryId: catId, currentCount: count, target: target, dayKey: day, now: now + 9999)
        XCTAssertEqual(capped, target)

        let stored = try db.queue.read { q in
            try Int.fetchOne(q, sql: "SELECT count FROM adhkar_state WHERE item_id = ? AND day_key = ?", arguments: [itemId, day])
        }
        XCTAssertEqual(stored, target)
    }

    func testTasbihPresetsTapAndBookmarksWritePaths() throws {
        let db = try makeDb()
        let day = "2026-11-18"
        let now: Int64 = 1_794_988_800_000

        try db.ensureDefaultTasbihPresets(now: now)
        let firstUuid = try XCTUnwrap(try db.queue.read { q in
            try String.fetchOne(q, sql: "SELECT uuid FROM tasbih_counters WHERE deleted = 0 ORDER BY sort_order LIMIT 1")
        })

        try db.recordTasbihTap(counterUuid: firstUuid, target: 33, newCount: 33, dayKey: day, now: now + 10)
        try db.queue.read { q in
            let row = try Row.fetchOne(q, sql: "SELECT count, total_lifetime FROM tasbih_counters WHERE uuid = ?", arguments: [firstUuid])
            XCTAssertEqual(row?["count"] as Int?, 1)
            XCTAssertEqual(row?["total_lifetime"] as Int?, 1)
            XCTAssertEqual(try Int.fetchOne(q, sql: "SELECT COUNT(*) FROM tasbih_sessions WHERE counter_uuid = ?", arguments: [firstUuid]), 1)
            XCTAssertEqual(try Int.fetchOne(q, sql: "SELECT COUNT(*) FROM streak_days WHERE kind = 'tasbih' AND day_key = ?", arguments: [day]), 1)
        }

        let added = try db.toggleBookmark(page: 1, lineNumber: 1, ayahNumber: nil, labelAr: "الفاتحة", now: now + 20)
        XCTAssertTrue(added)
        let removed = try db.toggleBookmark(page: 1, lineNumber: 1, ayahNumber: nil, labelAr: "الفاتحة", now: now + 30)
        XCTAssertFalse(removed)
    }

    func testSelectCityZagazigAndComputePrayers() throws {
        let db = try makeDb()
        let matches = db.searchCities(query: "الزقازيق")
        let zagazig = try XCTUnwrap(matches.first { $0.nameAr.contains("الزقازيق") || $0.nameEn.localizedCaseInsensitiveContains("zagazig") },
                                    "expected الزقازيق in cities FTS/LIKE search")
        XCTAssertEqual(zagazig.timeZone, "Africa/Cairo")

        // Must commit location setting atomically without GRDB reentrancy
        try db.selectCity(zagazig, now: 1_794_988_800_000)
        let opts = db.engineOptions()
        XCTAssertEqual(opts.timeZone, "Africa/Cairo")
        XCTAssertEqual(opts.lat, zagazig.lat, accuracy: 1e-4)
        XCTAssertEqual(opts.lng, zagazig.lng, accuracy: 1e-4)

        let sched = try PrayerEngine.daySchedule("2026-11-18", opts)
        XCTAssertLessThan(sched.prayers[.fajr]!, sched.prayers[.dhuhr]!)
        XCTAssertLessThan(sched.prayers[.dhuhr]!, sched.prayers[.isha]!)

        let next = try PrayerEngine.next(sched.prayers[.isha]! + 60_000, opts)
        XCTAssertEqual(next.name, .fajr)

        let engine = PrayerEngine.bind(opts)
        let card = SmartCardResolver.resolve(now: sched.prayers[.dhuhr]! + 2 * 60 * 60_000, engine: engine)
        if card.kind == .next_prayer {
            XCTAssertEqual(card.actionLabel, "التقويم الهجري")
            XCTAssertEqual(card.actionScreen, "tools-hijri")
        }
    }

    func testAudioCatalogDecodesSnakeCaseKeys() throws {
        let json = """
        {
          "formatVersion": 1,
          "reciters": [
            {
              "folder": "Alafasy_128kbps",
              "reciter_id": "alafasy",
              "name_ar": "مشاري راشد العفاسي",
              "name_en": "Mishary Rashid Alafasy",
              "style": "murattal",
              "bitrate_kbps": 128,
              "word_segments_available": 0,
              "audio_url_template": "https://everyayah.com/data/Alafasy_128kbps/{SSSAAA}.mp3"
            }
          ]
        }
        """
        let cat = try JSONDecoder().decode(AudioCatalog.self, from: Data(json.utf8))
        XCTAssertEqual(cat.formatVersion, 1)
        XCTAssertEqual(cat.reciters.count, 1)
        XCTAssertEqual(cat.reciters[0].id, "alafasy")
        XCTAssertEqual(cat.reciters[0].nameAr, "مشاري راشد العفاسي")
        XCTAssertEqual(cat.reciters[0].audioUrlTemplate, "https://everyayah.com/data/Alafasy_128kbps/{SSSAAA}.mp3")
    }

    func testImportPreservesDeviceIdAndOrdersTasbihSessionAfterCounter() throws {
        let db = try makeDb()
        let localDeviceId = try db.deviceId()
        let now: Int64 = 1_764_300_000_000
        let counterUuid = "01933c9e-1111-7000-8000-000000000001"
        let sessionUuid = "01933c9e-2222-7000-8000-000000000002"
        let settingUuid = "01933c9e-3333-7000-8000-000000000003"
        let payload: JSONValue = .object([
            "reading": .array([]),
            "dhikr": .array([
                .object([
                    "uuid": .string(sessionUuid), "type": .string("tasbihSession"), "updatedAt": .number(Double(now)),
                    "counterUuid": .string(counterUuid), "countDelta": .number(3), "occurredAt": .number(Double(now)),
                ]),
                .object([
                    "uuid": .string(counterUuid), "type": .string("tasbihCounter"), "updatedAt": .number(Double(now)),
                    "deleted": .bool(false), "labelAr": .string("سبحان الله"), "dhikrText": .string("سبحان الله"),
                    "target": .number(33), "count": .number(3), "totalLifetime": .number(3), "sortOrder": .number(0),
                ]),
            ]),
            "prefs": .array([
                .object([
                    "uuid": .string(settingUuid), "type": .string("setting"), "updatedAt": .number(Double(now + 10_000)),
                    "key": .string("device_id"), "value": .string("attacker-device-id"),
                ]),
            ]),
            "meta": .array([]),
        ])
        let integrity = sha256Hex(CanonicalJSON.serialize(payload))
        let manifest: JSONValue = .object([
            "format": .string("sadaqa-backup"),
            "formatVersion": .number(1),
            "createdAt": .number(Double(now)),
            "deviceId": .string("other-device-0001"),
            "integrity": .string(integrity),
            "entities": .object(["reading": .number(0), "dhikr": .number(2), "prefs": .number(1), "meta": .number(0)]),
        ])
        let text = CanonicalJSON.serialize(.object(["manifest": manifest, "payload": payload]))
        _ = try db.importBackup(text: text, mode: "merge")
        XCTAssertEqual(try db.deviceId(), localDeviceId)
        try db.queue.read { q in
            XCTAssertEqual(try Int.fetchOne(q, sql: "SELECT COUNT(*) FROM tasbih_sessions WHERE uuid = ?", arguments: [sessionUuid]), 1)
        }
    }

    func testHijriIsTodayAdjustmentMatchesEngine() {
        let adjusted = HijriEngine.withAdjust("2026-11-18", 1)
        let unadjusted = HijriEngine.withAdjust("2026-11-18", 0)
        XCTAssertNotEqual(adjusted, unadjusted)
    }
